//! The Elliott structure checks against `fixtures/scenario_elliott.txt`.
//!
//! The fixture is generated by `reference/kestrel_reference/fixtures/scenario_elliott.py` from a
//! second implementation of the documented rules (`reference/kestrel_reference/elliott.py`). Every
//! sequence is listed rising and mirrored; per structure there is a valid sequence, one sequence
//! per rule that breaks only that rule, the sequence errors, and at every threshold the value just
//! below it, on it and just above it.

use std::collections::{BTreeSet, HashMap};

use kestrel_chartkit::indicator::elliott::{
    check_combination, check_correction, check_diagonal, check_impulse, check_triangle,
    identify_extended_wave, is_truncated_fifth, validate_combination, validate_correction,
    validate_diagonal, validate_impulse, validate_triangle, CombinationVariant, CorrectionOptions,
    CorrectionValidation, CorrectionVariant, DiagonalKind, DiagonalVariant, GuidelineDeviation,
    RuleViolation, SequenceError, TriangleOptions, TriangleVariant, WaveDirection, WaveSubdivision,
};
use kestrel_chartkit::indicator::zigzag_advanced::ZigZagNode;

const FIXTURE: &str = include_str!("fixtures/scenario_elliott.txt");
const QUALITY_TOLERANCE: f64 = 1e-12;

struct Row {
    case: &'static str,
    options: HashMap<&'static str, &'static str>,
    nodes: Vec<ZigZagNode>,
    expected: &'static str,
}

fn node(kind: &str, timestamp: i64, price: f64) -> ZigZagNode {
    ZigZagNode {
        timestamp,
        price,
        is_high: kind == "H",
        confirmed: true,
    }
}

fn rows(structure: &str) -> Vec<Row> {
    let rows: Vec<Row> = FIXTURE
        .lines()
        .filter(|line| !line.starts_with('#'))
        .map(|line| line.split('\t').collect::<Vec<_>>())
        .filter(|fields| fields[0] == structure)
        .map(|fields| Row {
            case: fields[1],
            options: fields[2]
                .split(' ')
                .filter(|option| *option != "-")
                .map(|option| option.split_once('=').expect("option is key=value"))
                .collect(),
            nodes: fields[3]
                .split(' ')
                .map(|text| {
                    let (kind, rest) = text.split_once('@').expect("node is kind@time:price");
                    let (time, price) = rest.split_once(':').expect("node is kind@time:price");
                    node(kind, time.parse().unwrap(), price.parse().unwrap())
                })
                .collect(),
            expected: fields[4],
        })
        .collect();
    assert!(!rows.is_empty(), "no fixture rows for {structure}");
    rows
}

fn error_text(error: SequenceError) -> String {
    match error {
        SequenceError::NodeCount { .. } => "error=count".to_string(),
        SequenceError::NotAlternating { index } => format!("error=alternation@{index}"),
        SequenceError::TimeOrder { index } => format!("error=time@{index}"),
        SequenceError::PivotPlacement { index } => format!("error=placement@{index}"),
    }
}

fn direction(direction: WaveDirection) -> &'static str {
    match direction {
        WaveDirection::Up => "up",
        WaveDirection::Down => "down",
    }
}

fn flag(value: bool) -> &'static str {
    if value {
        "1"
    } else {
        "0"
    }
}

fn names<'a>(items: impl Iterator<Item = &'a str>) -> String {
    let items: Vec<&str> = items.collect();
    if items.is_empty() {
        "-".to_string()
    } else {
        items.join(",")
    }
}

fn rules(violations: &[RuleViolation]) -> String {
    names(violations.iter().map(|v| v.rule.as_str()))
}

fn guidelines(deviations: &[GuidelineDeviation]) -> String {
    names(deviations.iter().map(|d| d.guideline.as_str()))
}

fn correction_variant(variant: CorrectionVariant) -> &'static str {
    match variant {
        CorrectionVariant::Zigzag => "zigzag",
        CorrectionVariant::Flat => "flat",
        CorrectionVariant::ExpandedFlat => "expanded_flat",
        CorrectionVariant::RunningFlat => "running_flat",
    }
}

/// Compares `key=value` fields; `quality` numerically, everything else as text.
fn assert_fields(case: &str, actual: &str, expected: &str) {
    fn split(text: &str) -> Vec<(&str, &str)> {
        text.split(' ')
            .map(|field| field.split_once('=').unwrap_or((field, "")))
            .collect()
    }
    let (actual_fields, expected_fields) = (split(actual), split(expected));
    assert_eq!(
        actual_fields.len(),
        expected_fields.len(),
        "{case}: got `{actual}`, expected `{expected}`"
    );
    for ((key, value), (expected_key, expected_value)) in actual_fields.iter().zip(&expected_fields)
    {
        assert_eq!(
            key, expected_key,
            "{case}: got `{actual}`, expected `{expected}`"
        );
        if *key == "quality" {
            let (got, want): (f64, f64) = (value.parse().unwrap(), expected_value.parse().unwrap());
            assert!(
                (got - want).abs() <= QUALITY_TOLERANCE,
                "{case}: quality {got}, expected {want}"
            );
        } else {
            assert_eq!(
                value, expected_value,
                "{case}: got `{actual}`, expected `{expected}`"
            );
        }
    }
}

fn correction_options(options: &HashMap<&str, &str>) -> CorrectionOptions {
    let mut parsed = CorrectionOptions::default();
    for (&key, &value) in options {
        match key {
            "wave_a" => {
                parsed.wave_a = Some(match value {
                    "five" => WaveSubdivision::Five,
                    "three" => WaveSubdivision::Three,
                    other => panic!("unknown subdivision {other}"),
                })
            }
            "flat_b_typical_max" => parsed.flat_b_typical_max = value.parse().unwrap(),
            other => panic!("unknown correction option {other}"),
        }
    }
    parsed
}

fn correction_text(v: &CorrectionValidation) -> String {
    format!(
        "direction={} variant={} valid={} violations={} guidelines={} quality={:?}",
        direction(v.direction),
        correction_variant(v.variant),
        flag(v.valid),
        rules(&v.violations),
        guidelines(&v.guidelines),
        v.pullback_quality
    )
}

#[test]
fn impulse_matches_reference() {
    for row in rows("impulse") {
        let checked = check_impulse(&row.nodes);
        let actual = match &checked {
            Err(error) => error_text(*error),
            Ok(v) => format!(
                "direction={} valid={} violations={} quality={:?}",
                direction(v.direction),
                flag(v.valid),
                rules(&v.violations),
                v.pullback_quality
            ),
        };
        assert_fields(row.case, &actual, row.expected);
        assert_eq!(validate_impulse(&row.nodes), checked.ok(), "{}", row.case);
    }
}

#[test]
fn diagonal_matches_reference() {
    for row in rows("diagonal") {
        let kind = match row.options["kind"] {
            "leading" => DiagonalKind::Leading,
            "ending" => DiagonalKind::Ending,
            other => panic!("unknown kind {other}"),
        };
        let checked = check_diagonal(&row.nodes, kind);
        let actual = match &checked {
            Err(error) => error_text(*error),
            Ok(v) => {
                assert_eq!(v.kind, kind, "{}", row.case);
                format!(
                    "direction={} variant={} valid={} violations={} overlap={}",
                    direction(v.direction),
                    match v.variant {
                        DiagonalVariant::Contracting => "contracting",
                        DiagonalVariant::Expanding => "expanding",
                    },
                    flag(v.valid),
                    rules(&v.violations),
                    flag(v.wave4_overlaps_wave1)
                )
            }
        };
        assert_fields(row.case, &actual, row.expected);
        assert_eq!(
            validate_diagonal(&row.nodes, kind),
            checked.ok(),
            "{}",
            row.case
        );
    }
}

#[test]
fn correction_matches_reference() {
    for row in rows("correction") {
        let options = correction_options(&row.options);
        let checked = check_correction(&row.nodes, &options);
        let actual = match &checked {
            Err(error) => error_text(*error),
            Ok(v) => correction_text(v),
        };
        assert_fields(row.case, &actual, row.expected);
        if row.options.is_empty() {
            assert_eq!(
                validate_correction(&row.nodes),
                checked.ok(),
                "{}",
                row.case
            );
        }
    }
}

#[test]
fn triangle_matches_reference() {
    for row in rows("triangle") {
        let mut options = TriangleOptions::default();
        if let Some(tolerance) = row.options.get("barrier_tolerance") {
            options.barrier_tolerance = tolerance.parse().unwrap();
        }
        let checked = check_triangle(&row.nodes, &options);
        let actual = match &checked {
            Err(error) => error_text(*error),
            Ok(v) => format!(
                "direction={} variant={} running={} valid={} violations={}",
                direction(v.direction),
                match v.variant {
                    TriangleVariant::Contracting => "contracting",
                    TriangleVariant::Barrier => "barrier",
                    TriangleVariant::Expanding => "expanding",
                },
                flag(v.running),
                flag(v.valid),
                rules(&v.violations)
            ),
        };
        assert_fields(row.case, &actual, row.expected);
        if row.options.is_empty() {
            assert_eq!(validate_triangle(&row.nodes), checked.ok(), "{}", row.case);
        }
    }
}

#[test]
fn combination_matches_reference() {
    for row in rows("combination") {
        let options = correction_options(&row.options);
        let checked = check_combination(&row.nodes, &options);
        let actual = match &checked {
            Err(error) => error_text(*error),
            Ok(v) => {
                let segments: Vec<String> = v
                    .segments
                    .iter()
                    .map(|s| {
                        format!(
                            "{}/{}/{}/{}",
                            correction_variant(s.variant),
                            flag(s.valid),
                            rules(&s.violations),
                            guidelines(&s.guidelines)
                        )
                    })
                    .collect();
                format!(
                    "variant={} valid={} segments={}",
                    match v.variant {
                        CombinationVariant::DoubleThree => "double_three",
                        CombinationVariant::TripleThree => "triple_three",
                    },
                    flag(v.valid),
                    segments.join(";")
                )
            }
        };
        assert_fields(row.case, &actual, row.expected);
        if row.options.is_empty() {
            assert_eq!(
                validate_combination(&row.nodes),
                checked.ok(),
                "{}",
                row.case
            );
        }
    }
}

#[test]
fn extension_and_truncation_match_reference() {
    for row in rows("measures") {
        let actual = format!(
            "extended={} truncated={}",
            identify_extended_wave(&row.nodes).map_or("none".to_string(), |wave| wave.to_string()),
            is_truncated_fifth(&row.nodes).map_or("none", flag)
        );
        assert_fields(row.case, &actual, row.expected);
    }
}

/// Every rule and every guideline has a sequence in the fixture that departs from it and from
/// nothing else, in both directions.
#[test]
fn every_rule_and_guideline_has_a_sequence_that_breaks_only_it() {
    let field = |row: &Row, key: &str| -> Option<&'static str> {
        row.expected
            .split(' ')
            .filter_map(|f| f.split_once('='))
            .find(|(k, _)| *k == key)
            .map(|(_, value)| value)
    };
    let alone = |structure: &str, key: &str, other: Option<&str>| -> BTreeSet<(String, String)> {
        rows(structure)
            .iter()
            .filter(|row| other.is_none_or(|o| field(row, o) == Some("-")))
            .filter_map(|row| Some((field(row, key)?, field(row, "direction")?)))
            .filter(|(value, _)| *value != "-" && !value.contains(','))
            .map(|(value, direction)| (value.to_string(), direction.to_string()))
            .collect()
    };
    let expect = |found: BTreeSet<(String, String)>, wanted: &[&str], what: &str| {
        for name in wanted {
            for direction in ["up", "down"] {
                assert!(
                    found.contains(&(name.to_string(), direction.to_string())),
                    "{what}: no {direction} sequence breaks only {name}"
                );
            }
        }
        let known: BTreeSet<&str> = wanted.iter().copied().collect();
        for (name, _) in &found {
            assert!(
                known.contains(name.as_str()),
                "{what}: {name} is not listed here"
            );
        }
    };

    expect(
        alone("impulse", "violations", None),
        &[
            "wave2_no_full_retrace",
            "wave3_not_shortest",
            "wave4_no_overlap",
        ],
        "impulse rules",
    );
    expect(
        alone("diagonal", "violations", None),
        &["wave2_no_full_retrace", "wave3_not_shortest"],
        "diagonal rules",
    );
    expect(
        alone("correction", "violations", None),
        &[
            "wave_c_must_extend_past_b",
            "zigzag_b_not_beyond_start_of_a",
            "flat_b_min_retrace",
        ],
        "correction rules",
    );
    expect(
        alone("correction", "guidelines", Some("violations")),
        &[
            "zigzag_b_retrace_bound",
            "zigzag_c_ends_beyond_a",
            "flat_c_ends_beyond_a",
            "flat_b_retrace_bound",
        ],
        "correction guidelines",
    );
    expect(
        alone("triangle", "violations", None),
        &[
            "triangle_c_not_beyond_a",
            "triangle_d_not_beyond_b",
            "triangle_e_not_beyond_c",
            "expanding_triangle_c_beyond_a",
            "expanding_triangle_d_beyond_b",
            "expanding_triangle_e_beyond_c",
            "expanding_triangle_b_retrace",
            "expanding_triangle_c_retrace",
            "expanding_triangle_d_retrace",
        ],
        "triangle rules",
    );
}

/// The sentences that go with the identifiers are part of the data contract.
#[test]
fn details_of_rules_and_guidelines_are_fixed() {
    let mut seen: HashMap<String, String> = HashMap::new();
    let mut note = |name: &str, detail: &str| {
        let previous = seen.insert(name.to_string(), detail.to_string());
        assert!(
            previous.is_none_or(|p| p == detail),
            "{name} has two details"
        );
    };
    for row in rows("impulse") {
        for v in check_impulse(&row.nodes).map_or(Vec::new(), |v| v.violations) {
            note(&v.rule, &v.detail);
        }
    }
    for row in rows("correction") {
        if let Ok(v) = check_correction(&row.nodes, &correction_options(&row.options)) {
            for x in &v.violations {
                note(&x.rule, &x.detail);
            }
            // The bound of this one guideline is an option and appears in its sentence.
            for x in &v.guidelines {
                if row.options.contains_key("flat_b_typical_max") {
                    assert_eq!(
                        x.detail,
                        "Wave B retraced more than a Flat's typical bound (120.0%)"
                    );
                } else {
                    note(&x.guideline, &x.detail);
                }
            }
        }
    }
    for row in rows("triangle") {
        for v in check_triangle(&row.nodes, &TriangleOptions::default())
            .map_or(Vec::new(), |v| v.violations)
        {
            note(&v.rule, &v.detail);
        }
    }

    let expected = [
        ("wave2_no_full_retrace", "Wave 2 retraced beyond the start of wave 1"),
        ("wave3_not_shortest", "Wave 3 is the shortest of waves 1, 3, and 5"),
        ("wave4_no_overlap", "Wave 4 entered wave 1's price territory"),
        (
            "wave_c_must_extend_past_b",
            "Wave C did not continue past wave B in wave A's direction",
        ),
        ("zigzag_b_not_beyond_start_of_a", "Wave B moved beyond the start of wave A"),
        ("flat_b_min_retrace", "Wave B retraced less than 90% of wave A"),
        (
            "zigzag_b_retrace_bound",
            "Wave B retraced more than a Zigzag's typical bound (78.6%) without qualifying as a Flat",
        ),
        ("zigzag_c_ends_beyond_a", "Wave C did not end beyond the end of wave A"),
        ("flat_c_ends_beyond_a", "Wave C did not end beyond the end of wave A"),
        (
            "flat_b_retrace_bound",
            "Wave B retraced more than a Flat's typical bound (138.2%)",
        ),
        ("triangle_c_not_beyond_a", "Wave C moved beyond the end of wave A"),
        ("triangle_d_not_beyond_b", "Wave D moved beyond the end of wave B"),
        ("triangle_e_not_beyond_c", "Wave E moved beyond the end of wave C"),
        ("expanding_triangle_c_beyond_a", "Wave C did not move beyond the end of wave A"),
        ("expanding_triangle_d_beyond_b", "Wave D did not move beyond the end of wave B"),
        ("expanding_triangle_e_beyond_c", "Wave E did not move beyond the end of wave C"),
        (
            "expanding_triangle_b_retrace",
            "Wave B retraced less than 100% or more than 150% of wave A",
        ),
        (
            "expanding_triangle_c_retrace",
            "Wave C retraced less than 100% or more than 150% of wave B",
        ),
        (
            "expanding_triangle_d_retrace",
            "Wave D retraced less than 100% or more than 150% of wave C",
        ),
    ];
    let expected: HashMap<String, String> = expected
        .iter()
        .map(|(name, detail)| (name.to_string(), detail.to_string()))
        .collect();
    assert_eq!(seen, expected);
}

// ---------------------------------------------------------------------------------------------
// The grid over the correction forms
// ---------------------------------------------------------------------------------------------

fn asserted(text: &str) -> Option<WaveSubdivision> {
    match text {
        "-" => None,
        "five" => Some(WaveSubdivision::Five),
        "three" => Some(WaveSubdivision::Three),
        other => panic!("unknown subdivision {other}"),
    }
}

/// `[0, A, B, C]` with wave A running in `direction`.
fn correction_nodes(direction: WaveDirection, prices: [f64; 4]) -> Vec<ZigZagNode> {
    let first_is_high = direction == WaveDirection::Down;
    prices
        .iter()
        .enumerate()
        .map(|(i, &price)| ZigZagNode {
            timestamp: 60 * i as i64,
            price,
            is_high: (i % 2 == 0) == first_is_high,
            confirmed: true,
        })
        .collect()
}

#[test]
fn correction_grid_matches_reference() {
    let mut cells = 0;
    for line in FIXTURE
        .lines()
        .filter(|l| l.starts_with("correction_grid\t"))
    {
        let fields: Vec<&str> = line.split('\t').collect();
        let direction = match fields[1] {
            "up" => WaveDirection::Up,
            "down" => WaveDirection::Down,
            other => panic!("unknown direction {other}"),
        };
        let options = CorrectionOptions {
            wave_a: asserted(fields[2]),
            ..CorrectionOptions::default()
        };
        let abc: Vec<f64> = fields[3].split(' ').map(|p| p.parse().unwrap()).collect();
        for cell in fields[4].split(' ') {
            let (c, code) = cell.split_once(':').expect("cell is price:code");
            let nodes = correction_nodes(direction, [abc[0], abc[1], abc[2], c.parse().unwrap()]);
            let v = check_correction(&nodes, &options).expect("a pivot sequence up to B");
            let actual = format!(
                "{}{}",
                match v.variant {
                    CorrectionVariant::Zigzag => "Z",
                    CorrectionVariant::Flat => "F",
                    CorrectionVariant::ExpandedFlat => "E",
                    CorrectionVariant::RunningFlat => "R",
                },
                flag(v.valid)
            );
            assert_eq!(actual, code, "{line}: C = {c}");
            assert_eq!(v.direction, direction, "{line}");
            cells += 1;
        }
    }
    assert!(cells > 1000, "the grid has only {cells} cells");
}

/// Every sequence falls into exactly one form, and a valid one into exactly one valid form.
///
/// The four forms are stated here once more, each as its own condition on whole numbers: wave A
/// is 1000 long, `k` is the retracement of wave B in thousandths, and C is given by its position
/// relative to the ends of B and A. The conditions are the rows of the table documented on
/// `check_correction`; that exactly one of them holds for every cell is what this test adds to the
/// comparison with the reference.
#[test]
fn every_correction_falls_into_exactly_one_form() {
    for direction in [WaveDirection::Up, WaveDirection::Down] {
        for wave_a in [
            None,
            Some(WaveSubdivision::Five),
            Some(WaveSubdivision::Three),
        ] {
            let options = CorrectionOptions {
                wave_a,
                ..CorrectionOptions::default()
            };
            for k in 1..=2000_i64 {
                // The end of B, as a rising correction from 3000 to 4000.
                let b = 4000 - k;
                for c in [b - 1, b, b + 1, 3999, 4000, 4001, 4700, 9000] {
                    let rising = [3000, 4000, b, c];
                    let prices = rising.map(|p| match direction {
                        WaveDirection::Up => p as f64,
                        WaveDirection::Down => -(p as f64),
                    });
                    let v = check_correction(&correction_nodes(direction, prices), &options)
                        .expect("a pivot sequence up to B");

                    let flat_family = match wave_a {
                        Some(WaveSubdivision::Five) => false,
                        Some(WaveSubdivision::Three) => true,
                        None => k >= 900,
                    };
                    let b_beyond_start_of_a = k > 1000;
                    let c_beyond_a = c > 4000;
                    let forms = [
                        (CorrectionVariant::Zigzag, !flat_family),
                        (
                            CorrectionVariant::Flat,
                            flat_family && (!b_beyond_start_of_a || (k <= 1050 && c_beyond_a)),
                        ),
                        (
                            CorrectionVariant::ExpandedFlat,
                            flat_family && k > 1050 && c_beyond_a,
                        ),
                        (
                            CorrectionVariant::RunningFlat,
                            flat_family && b_beyond_start_of_a && !c_beyond_a,
                        ),
                    ];
                    let matching: Vec<CorrectionVariant> = forms
                        .iter()
                        .filter(|(_, holds)| *holds)
                        .map(|(variant, _)| *variant)
                        .collect();
                    assert_eq!(
                        matching,
                        [v.variant],
                        "{direction:?} {wave_a:?} k={k} c={c}"
                    );

                    let three_waves = c > b;
                    let family_rule_holds = match wave_a {
                        Some(WaveSubdivision::Five) => !b_beyond_start_of_a,
                        Some(WaveSubdivision::Three) => k >= 900,
                        None => true,
                    };
                    assert_eq!(
                        v.valid,
                        three_waves && family_rule_holds,
                        "{direction:?} {wave_a:?} k={k} c={c}"
                    );
                }
            }
        }
    }
}
